# Generated by scripts/homebrew/formula.mjs in https://github.com/EvanZhang008/open-walnut for open-walnut 0.6.13.
class OpenWalnut < Formula
  desc "Personal AI: tasks, notes and Claude Code sessions on your own machine"
  homepage "https://github.com/EvanZhang008/open-walnut"
  version "0.6.13"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.13/open-walnut-0.6.13-darwin-arm64.tar.gz", using: :nounzip
      sha256 "76fbd86284ae65934a7919b7fe7588988825ad57068bff94cbaeb91f80ae746b"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.13/open-walnut-0.6.13-darwin-x64.tar.gz", using: :nounzip
      sha256 "20464bdfd6382ab67d449f5a524750339f89d1d77fc0b8bc3daf2bb7f57eca85"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.13/open-walnut-0.6.13-linux-arm64.tar.gz", using: :nounzip
      sha256 "d30951ee01df8f87e3681688fbf11bde913e067b48d55eee5d612643ffd794b8"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.13/open-walnut-0.6.13-linux-x64.tar.gz", using: :nounzip
      sha256 "3dee09da113bfc2e2fafb42bc1df34c3acce4edd6d13cfe3f792da477e4fd730"
    end
  end

  def install
    libexec.install Dir["open-walnut-*.tar.gz"].first => "open-walnut.tar.gz"
    # Scripts, not links: the cleaner drops a link whose target is not there yet.
    bin.write_exec_script libexec/"app/bin/walnut", libexec/"app/bin/open-walnut"
  end

  # After Homebrew's install-name pass over the keg, which the archive must skip.
  # The packed copy goes once unpacked, so running these again changes nothing.
  post_install_steps do
    if_path_exists "open-walnut.tar.gz", base: :libexec do
      remove "app", base: :libexec, recursive: true
      mkdir_p "app", base: :libexec
      run "tar", args: ["-xzf", "{{libexec}}/open-walnut.tar.gz", "-C", "{{libexec}}/app", "--strip-components=1"],
                 writable_paths: ["app"], writable_base: :libexec
      remove "open-walnut.tar.gz", base: :libexec
    end
  end

  def caveats
    <<~EOS
      Start it with:
        walnut web
      Walnut keeps itself up to date: it installs new releases when it starts.
      Its sessions run Claude Code: https://claude.com/product/claude-code
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/walnut --version")
  end
end
